const M = "<the scratch layout root>";
const add = (p) => "*** Begin Patch\n*** Add File: " + p + "\n+# probe\n*** End Patch\n";
const cases = [
  ["inside-workspace", add("probe-inside.txt")],
  ["outside-absolute-denied", add(M + "/records/direct.txt")],
  ["outside-via-symlink", add("l-rec/via-symlink.txt")],
  ["outside-via-dotdot", add("../records/dotdot.txt")],
  ["outside-not-granted", add("<a folder that is neither granted nor denied>/probe-ungranted.txt")],
  ["workspace-dot-codex", add(".codex/config.toml")],
  ["update-existing-record", "*** Begin Patch\n*** Update File: " + M + "/records/existing.txt\n@@\n-original record\n+tampered record\n*** End Patch\n"],
  ["delete-existing-record", "*** Begin Patch\n*** Delete File: " + M + "/records/existing.txt\n*** End Patch\n"],
];
for (const [label, patch] of cases) {
  try {
    const r = await tools.apply_patch(patch);
    text(label + " => RETURNED " + JSON.stringify(r).slice(0, 260));
  } catch (e) {
    text(label + " => THREW " + String(e && e.message ? e.message : e).slice(0, 260));
  }
}
